import{_ as e,o as a,c as l,a2 as o}from"./chunks/framework.CAKCj7G0.js";const S=JSON.parse('{"title":"State Hook","description":"","frontmatter":{},"headers":[],"relativePath":"DuOneClass/09.react/4-2.StateHook.md","filePath":"DuOneClass/09.react/4-2.StateHook.md"}'),i={name:"DuOneClass/09.react/4-2.StateHook.md"};function s(r,t,n,p,_,c){return a(),l("div",null,[...t[0]||(t[0]=[o('<h1 id="state-hook" tabindex="-1">State Hook <a class="header-anchor" href="#state-hook" aria-label="Permalink to &quot;State Hook&quot;">​</a></h1><p>State Hook是一个在函数组件中使用的函数（useState），用于在函数组件中使用状态</p><p>useState</p><ul><li>函数有一个参数，这个参数的值表示状态的默认值</li><li>函数的返回值是一个数组，该数组一定包含两项 <ul><li>第一项：当前状态的值</li><li>第二项：改变状态的函数</li></ul></li></ul><p>一个函数组件中可以有多个状态，这种做法非常有利于横向切分关注点。</p><p><img src="https://s2.loli.net/2024/08/20/EDe9Tn1r4bMockW.png" alt="image-20240820120737308"></p><p><strong>注意的细节</strong></p><ol><li>useState最好写到函数的起始位置，便于阅读</li><li>useState严禁出现在代码块（判断、循环）中</li><li>useState返回的函数（数组的第二项），引用不变（节约内存空间）</li><li>使用函数改变数据，若数据和之前的数据完全相等（使用Object.is比较），不会导致重新渲染，以达到优化效率的目的。</li><li>使用函数改变数据，传入的值不会和原来的数据进行合并，而是直接替换。</li><li>如果要实现强制刷新组件 <ol><li>类组件：使用forceUpdate函数</li><li>函数组件：使用一个空对象的useState</li></ol></li><li><strong>如果某些状态之间没有必然的联系，应该分化为不同的状态，而不要合并成一个对象</strong></li><li>和类组件的状态一样，函数组件中改变状态可能是异步的（在DOM事件中），多个状态变化会合并以提高效率，此时，不能信任之前的状态，而应该使用回调函数的方式改变状态。如果状态变化要使用到之前的状态，尽量传递函数。</li></ol>',8)])])}const d=e(i,[["render",s]]);export{S as __pageData,d as default};
